export function authenticate(context) {
  // 只读取宿主绑定的 session；不接收 body.userId/body.roles/body.tenant。
  const principal = context.session?.principal;
  if (!principal?.authenticated || principal.realm !== REALM) {
    throw new DemoError(401, 'AUTHENTICATION_REQUIRED', '需要有效的合成演示会话');
  }
  return principal;
}

function requireAllowed(allowed, permission) {
  // B0：适用允许规则任一满足即允许；无匹配规则默认拒绝。
  if (!allowed) {
    throw new DemoError(403, 'FORBIDDEN', `未满足 ${permission} 的授权条件`);
  }
}

function consumeFailure(point) {
  if (failures.delete(point)) {
    throw new DemoError(503, 'TRANSACTION_FAILED', `合成故障：${point}`);
  }
}

try {
  const result = await dispatch({ method, path, context });
  return { status: 200, body: result };

} catch (error) {
  if (error instanceof DemoError) {
    return { status: error.status, body: { error: error.code, message: error.message } };
  }

if (request.state !== 'DRAFT') {
  throw new DemoError(409, 'INVALID_STATE', '只有 DRAFT 申请可以提交');
}

if (!(request.amount > 0)) {
  throw new DemoError(422, 'INVALID_AMOUNT', '提交金额必须大于 0 元');
}

return {
  request: submitted,
  nextCandidates: workflow.candidatesFor('审批人', submitted),
};

if (request.state !== 'SUBMITTED') {
  throw new DemoError(409, 'INVALID_STATE', '只有 SUBMITTED 申请可以审批');
}

if (!(request.amount <= 5000)) {
  throw new DemoError(422, 'AMOUNT_LIMIT', '审批金额不能超过 5000 元');
}

return {
  request: approved,
  receipt: { status: receiptStatus, mode: 'simulated' },
  observerCandidates: workflow.candidatesFor('观察者', approved),
};

} catch (error) {
  receipt.recordFailure(approved, error);
  receiptStatus = 'failed';
  // 事务已经提交；这里记录回执失败，不回滚 APPROVED 和审计。
}

return {
  request,
  viewedBy: principal.id,
  applicantCandidates: workflow.candidatesFor('申请人', request),
  observerCandidates: workflow.candidatesFor('观察者', request),
};

setState(id, nextState) {
  const request = get(id, pending);
  pending.requests[id] = { ...request, state: nextState };
  return get(id, pending);

appendAudit(event) {
  consumeFailure('audit-write');
  pending.audits.push({ ...event });
},

const result = work(tx);
if (result?.then) throw new TypeError('此演示仅支持同步事务回调');
consumeFailure('transaction-commit');
state = pending;
return result;

async send(request, runtimeTarget) {
  // 只写内存以模拟发送，没有邮件、网络或外部通知。
  if (failNextSend) {
    failNextSend = false;
    throw new Error('合成回执发送失败');
  }
  // 目的地来自运行时参数；只保存其标签，不验证或访问任何地址。
  sent.push({ requestId: request.id, state: request.state, target: runtimeTarget, mode: 'simulated' });
},

recordFailure(request, error) {
  failures.push({ requestId: request.id, message: error.message });
},
